// ---- AUTOCOMPLETE ----
function AutoInput({value,onChange,items,placeholder,style:sx}){
  const[open,setOpen]=useState(false);const[hi,setHi]=useState(-1);const ref=useRef(null);
  const filtered=useMemo(()=>{if(!value||!items.length)return[];const clean=s=>s.toLowerCase().replace(/[^a-z0-9]/g,"");const v=clean(value);return items.filter(i=>clean(i).includes(v)).sort((a,b)=>Number(clean(b).startsWith(v))-Number(clean(a).startsWith(v))).slice(0,10);},[value,items]);
  const show=open&&filtered.length>0&&value.length>0;
  return(<div style={{position:"relative",minWidth:0,...sx}}><input aria-label={placeholder} autoComplete="off" value={value} onChange={e=>{onChange(e.target.value);setOpen(true);setHi(-1);}} onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),150)} onKeyDown={e=>{if(e.key==="Escape"){setOpen(false);return;}if(!show)return;if(e.key==="ArrowDown"){e.preventDefault();setHi(p=>Math.min(p+1,filtered.length-1));}else if(e.key==="ArrowUp"){e.preventDefault();setHi(p=>Math.max(p-1,0));}else if(e.key==="Enter"&&hi>=0){e.preventDefault();onChange(filtered[hi]);setOpen(false);}}} placeholder={placeholder} style={{...IS,...sx}} ref={ref}/>{show&&(<div style={{position:"absolute",top:"100%",right:0,width:"auto",minWidth:160,maxWidth:260,maxHeight:192,overflowY:"auto",background:"#111118",border:"1px solid #2a2a3e",borderRadius:6,zIndex:50,marginTop:2,boxShadow:"0 8px 24px rgba(0,0,0,0.6)"}}>{filtered.map((item,i)=>(<div key={item} onMouseDown={e=>{e.preventDefault();onChange(item);setOpen(false);}} style={{padding:"6px 10px",fontSize:12,color:i===hi?"#e0e0e0":"#a0a0b8",background:i===hi?"#1a1a2e":"transparent",cursor:"pointer",borderBottom:"1px solid #1a1a28",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{item}</div>))}</div>)}</div>);
}

