  const data=useMemo(()=>!sort?rows:[...rows].sort((a,b)=>{const av=a[sort.key],bv=b[sort.key];const v=typeof av==="number"&&typeof bv==="number"?av-bv:String(av??"").localeCompare(String(bv??""));return sort.dir==="desc"?-v:v;}),[rows,sort]);
