const entryNumber = v => v !== null && v !== undefined && String(v).trim() !== "" && Number.isFinite(Number(v));
const uniqueNames = names => [...new Map(names.filter(Boolean).map(n=>[normalizeName(n),n.trim()])).values()];
function newSmartLeg(previous, sport, league, teaser=false){return {id:uid(),smart:true,sport:previous?.sport||sport,league:previous?.league||league,marketType:teaser?"Spread":previous?.marketType||"Spread",team:"",participant:"",propStat:previous?.propStat||"",overUnder:previous?.overUnder||"Over",line:"",selection:"",lineMode:"original"};}
function smartLegLine(leg,teaser,points){
  if(!entryNumber(leg.line))return "";
  const n=Number(leg.line);
  if(!teaser||leg.lineMode==="final")return n;
  return r2(n+(leg.marketType==="Total"?(leg.overUnder==="Under"?1:-1):1)*Number(points));
}
function smartLegText(leg,teaser,points){
  if(!leg.smart)return [leg.selection,leg.line].filter(v=>v!==""&&v!=null).join(" ").trim();
  const line=smartLegLine(leg,teaser,points);
  if(leg.marketType==="Total")return (leg.team||"?")+" "+buildDisplay("Total","",line,leg.overUnder);
  return buildDisplay(leg.marketType,leg.team,line,leg.overUnder,leg.participant,leg.propStat);
}
function validSmartLeg(leg,teaser,points){
  if(!leg.smart)return !!(leg.selection||"").trim();
  if(teaser&&!["Spread","Total"].includes(leg.marketType))return false;
  if(leg.marketType!=="Moneyline"&&!entryNumber(leg.line))return false;
  if(leg.marketType!=="Player Prop"&&!(leg.team||"").trim())return false;
  if(leg.marketType==="Player Prop"&&(!(leg.participant||"").trim()||!leg.propStat))return false;
  return !smartLegText(leg,teaser,points).includes("?");
}
function SmartLegEditor({leg,index,teaser,points,sports,customTeams,customPlayers,roster,onChange,onRemove,onDuplicate}){
  const sport=leg.sport||"Football", league=leg.league||"NFL", prop=leg.marketType==="Player Prop";
  const players=uniqueNames([...getPlayers(sport,customPlayers,league,roster),...(league==="NFL"?roster.map(p=>p.name):[])]);
  const change=(key,value)=>onChange({...leg,[key]:value});
  return <div style={{background:"#0d0d14",border:"1px solid #292940",borderRadius:10,padding:12,marginBottom:10}}>
    <div style={{display:"flex",justifyContent:"space-between",gap:8,marginBottom:10}}><strong style={{fontSize:12,color:"#a5b4fc"}}>LEG {index+1}</strong><div style={{display:"flex",gap:6}}><button onClick={onDuplicate} style={BS}>Duplicate</button>{onRemove&&<button aria-label={"Remove leg "+(index+1)} onClick={onRemove} style={BS}>×</button>}</div></div>
    {!leg.smart?<><Lb>Saved selection</Lb><input aria-label="Saved selection" value={leg.selection||""} onChange={e=>change("selection",e.target.value)} style={IS}/><Lb>Line</Lb><input value={leg.line??""} onChange={e=>change("line",e.target.value)} style={IS} aria-label="Line"/><div style={{fontSize:11,color:"#8888a5",marginTop:6}}>Existing leg kept as entered. New legs use the guided builder.</div></>:<>
      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:8}}><select aria-label="Leg sport" style={{...SS,flex:1}} value={sport} onChange={e=>onChange({...newSmartLeg(null,e.target.value,sports.find(s=>s.name===e.target.value)?.leagues[0]||"",teaser),id:leg.id})}>{sports.map(s=><option key={s.name}>{s.name}</option>)}</select><select aria-label="Leg league" style={{...SS,flex:1}} value={league} onChange={e=>change("league",e.target.value)}>{(sports.find(s=>s.name===sport)?.leagues||[]).map(l=><option key={l}>{l}</option>)}</select><select aria-label="Leg market" style={{...SS,flex:1}} value={leg.marketType} onChange={e=>onChange({...leg,marketType:e.target.value,line:""})}>{(teaser?[...(!["Spread","Total"].includes(leg.marketType)?[leg.marketType]:[]),"Spread","Total"]:["Spread","Moneyline","Total","Player Prop"]).map(m=><option key={m}>{m}</option>)}</select></div>
      {teaser&&!["Spread","Total"].includes(leg.marketType)&&<div role="alert" style={{color:"#f59e0b",fontSize:12}}>Choose Spread or Total for this teaser leg.</div>}
      <Lb>{prop?"Player":leg.marketType==="Total"?"Game / matchup":"Team"}</Lb><AutoInput value={prop?leg.participant:leg.team} onChange={v=>{const p=roster.find(p=>p.name===v);onChange({...leg,[prop?"participant":"team"]:v,...(prop&&!leg.propStat&&p&&league==="NFL"?{propStat:p.position==="QB"?"Pass Yds":p.position==="RB"||p.position==="FB"?"Rush Yds":p.position==="K"?"Kicking Pts":"Rec Yds"}:{})});}} items={prop?players:getTeams(league,customTeams)} placeholder={prop?"Start typing a player…":leg.marketType==="Total"?"e.g. Chiefs vs Bills":"Start typing a team…"}/>
      {prop&&<><Lb>Stat</Lb><select aria-label="Leg stat" value={leg.propStat} onChange={e=>onChange({...leg,propStat:e.target.value,...(e.target.value==="Anytime TD"?{line:"0.5",overUnder:"Over"}:{})})} style={SS}><option value="">Choose stat…</option>{pstats(sport).map(s=><option key={s}>{s}</option>)}</select></>}
      <div style={{display:"flex",gap:8,marginTop:8,alignItems:"end"}}>{(prop||leg.marketType==="Total")&&<div style={{flex:1}}><Lb>Direction</Lb><select aria-label="Leg direction" value={leg.overUnder} onChange={e=>change("overUnder",e.target.value)} style={SS}><option>Over</option><option>Under</option></select></div>}{leg.marketType!=="Moneyline"&&<div style={{flex:1}}><Lb>{teaser&&leg.lineMode!=="final"?"Original line":"Line"}</Lb><input aria-label="Leg line" inputMode="decimal" value={leg.line} onChange={e=>change("line",e.target.value)} style={IS}/></div>}</div>
      {teaser&&<div style={{marginTop:8}}><label style={{fontSize:12,color:"#aaaac0"}}><input type="checkbox" checked={leg.lineMode==="final"} onChange={e=>change("lineMode",e.target.checked?"final":"original")} aria-label="Input"/> I entered the adjusted line</label><div style={{fontSize:12,color:"#22c55e",marginTop:5}}>Adjusted selection: {smartLegText(leg,true,points)}</div></div>}
      {!teaser&&<div style={{fontSize:12,color:"#aaaac0",marginTop:8}}>{smartLegText(leg,false,points)}</div>}
    </>}
  </div>;
}

